const SECTIONS="ABCDEFGHIJKLM".split("");
const DAYS=["Pazartesi","Salı","Çarşamba","Perşembe","Cuma"];
const BRANCHES=["Matematik","Türkçe","Fen Bilimleri","Sosyal Bilgiler","İngilizce","Din Kültürü","Beden Eğitimi","Müzik","Görsel Sanatlar","Bilişim"];
const state={teachers:[],attendance:[],logs:[],announcements:[],selectedTeacher:null,online:navigator.onLine};
const $=id=>document.getElementById(id);
const esc=s=>String(s??"").replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
function toast(m){const e=$("toast");e.textContent=m;e.classList.add("show");clearTimeout(window.__t);window.__t=setTimeout(()=>e.classList.remove("show"),2400)}
function show(id){document.querySelectorAll(".screen").forEach(x=>x.classList.remove("active"));$(id).classList.add("active")}
function subview(prefix,id,title){const root=$(prefix+"Nav"); if(root)root.querySelectorAll(".nav-btn").forEach(b=>b.classList.toggle("active",(b.dataset[prefix+"-view"]||"")===id));document.querySelectorAll(prefix==="admin"?"#adminApp .subview":"#teacherApp .subview").forEach(x=>x.classList.remove("active"));$(id).classList.add("active");$(prefix+"PageTitle").textContent=title}
async function loadTeachers(){try{const snap=await getDocs(collection(db,"teachers"));state.teachers=snap.docs.map(d=>({id:d.id,...d.data()}));if(!state.teachers.length){for(const t of seedTeachers){const ref=await addDoc(collection(db,"teachers"),{...t,createdAt:serverTimestamp(),active:true});state.teachers.push({id:ref.id,...t,active:true})}} state.teachers.sort((a,b)=>(a.name||"").localeCompare(b.name||"","tr"));renderTeacherChoices();renderAdminTeachers();return state.teachers}catch(e){console.error(e);state.teachers=seedTeachers.map((x,i)=>({id:"local-"+i,...x,active:true}));renderTeacherChoices();renderAdminTeachers();return state.teachers}}
function renderTeacherChoices(){const q=($("teacherSearch")?.value||"").toLocaleLowerCase("tr-TR");const arr=state.teachers.filter(t=>(t.name||"").toLocaleLowerCase("tr-TR").includes(q)&&t.active!==false);$("teacherChoices").innerHTML=arr.map(t=>`<button class="teacher-choice" data-teacher="${t.id}"><span class="avatar">${esc((t.name||"?")[0])}</span><span><strong>${esc(t.name)}</strong><small>${esc(t.branch||"Branş belirtilmedi")}</small></span></button>`).join("");$("teacherChoiceEmpty").classList.toggle("hidden",arr.length>0);document.querySelectorAll("[data-teacher]").forEach(b=>b.onclick=()=>enterTeacher(b.dataset.teacher))}
function teacherName(id){return state.teachers.find(t=>t.id===id)?.name||"Öğretmen"}
async function enterTeacher(id){state.selectedTeacher=state.teachers.find(t=>t.id===id);if(!state.selectedTeacher)return;$("teacherNameMini").textContent=state.selectedTeacher.name;$("teacherAvatar").textContent=(state.selectedTeacher.name||"Ö")[0];show("teacherApp");renderTeacherHome();renderAttendance();renderTeacherStudents();renderTeacherSchedule();renderTeacherHistory();renderTeacherNotices();}
function renderTeacherHome(){const t=state.selectedTeacher||{};const schedule=getScheduleForTeacher(t);$("teacherHome").innerHTML=`<div class="hero-card"><div class="hero-row"><div><div class="eyebrow">HOŞ GELDİNİZ</div><h3>${esc(t.name)}</h3><p>${esc(t.branch||"")} • Size atanmış özel alan</p></div><button class="btn btn-blue" id="quickAttendance">✅ Sıradaki Yoklama</button></div></div><div class="stats-grid"><div class="stat-card accent-blue"><div class="stat-label">Bugünkü Ders</div><div class="stat-value">${schedule.filter(x=>x.dayIndex===new Date().getDay()-1).length||0}</div></div><div class="stat-card accent-green"><div class="stat-label">Haftalık Ders</div><div class="stat-value">${schedule.length}</div></div><div class="stat-card accent-red"><div class="stat-label">Son Yok</div><div class="stat-value">${state.attendance.filter(x=>x.teacherId===t.id&&x.status==="absent").length}</div></div><div class="stat-card accent-gold"><div class="stat-label">Durum</div><div class="stat-value">Aktif</div></div></div><div class="grid-2"><div class="panel"><h3>Sıradaki Ders</h3><div id="nextLessonBox"></div></div><div class="panel"><h3>Hızlı İşlemler</h3><div class="toolbar"><button class="btn btn-green" data-teacher-view="attendance">Yoklama Al</button><button class="btn btn-purple" data-teacher-view="mySchedule">Programım</button><button class="btn btn-muted" data-teacher-view="myStudents">Öğrenciler</button></div></div></div>`;const todayIndex=Math.max(0,new Date().getDay()-1);const next=schedule.find(x=>x.dayIndex===todayIndex&&x.slot>=1)||schedule[0];$("nextLessonBox").innerHTML=next?`<div class="slot"><strong>${next.slot}. Ders • ${next.className}</strong><small>${next.branch} • ${next.section} Şubesi</small><br><button class="btn btn-blue" style="margin-top:9px" id="nextAttendance">Yoklamayı Aç</button></div>`:`<div class="empty-small">Bugün için program bulunamadı.</div>`;$("quickAttendance")?.addEventListener("click",()=>openAttendanceFor(next));$("nextAttendance")?.addEventListener("click",()=>openAttendanceFor(next));document.querySelectorAll("[data-teacher-view]").forEach(b=>b.onclick=()=>subview("teacher",b.dataset.teacherView,b.textContent.replace(/^[^A-Za-zÇĞÜÖŞİçğüöşı0-9]+/,'').trim()))}
function getScheduleForTeacher(t){const all=[];const eligible=Object.entries(STUDENTS);let idx=0;for(let d=0;d<5;d++)for(let s=1;s<=7;s++){if((idx+d+s)%4===0){const key=eligible[(idx+d*7+s)%eligible.length][0];all.push({dayIndex:d,slot:s,className:key.split("-")[0]+". Sınıf",section:key.split("-")[1],branch:t.branch||BRANCHES[(idx+d)%BRANCHES.length]})}idx++}return all.slice(0,10)}
function renderTeacherSchedule(){const t=state.selectedTeacher||{};const sch=getScheduleForTeacher(t);$("mySchedule").innerHTML=`<div class="panel"><div class="toolbar"><span class="badge badge-blue">Haftalık Program</span></div><div class="schedule-grid">${DAYS.map((d,i)=>`<div class="day-col"><h4>${d}</h4>${sch.filter(x=>x.dayIndex===i).map(x=>`<div class="slot"><strong>${x.slot}. Ders • ${x.className}</strong><small>${x.section} Şubesi • ${x.branch}</small></div>`).join("")||'<div class="empty-small">Boş</div>'}</div>`).join("")}</div></div>`}
function renderAttendance(){$("attendance").innerHTML=`<div class="panel"><div class="toolbar"><select id="attClass" class="select" style="max-width:170px"><option value="">Sınıf</option>${[5,6,7,8].map(x=>`<option value="${x}">${x}. Sınıf</option>`).join("")}</select><select id="attSection" class="select" style="max-width:150px"><option value="">Şube</option>${SECTIONS.map(x=>`<option>${x}</option>`).join("")}</select><select id="attLesson" class="select" style="max-width:150px"><option value="">Ders</option>${Array.from({length:7},(_,i)=>`<option value="${i+1}">${i+1}. Ders</option>`).join("")}</select><button class="btn btn-blue" id="loadAtt">Öğrencileri Getir</button></div><div id="attendanceRows" class="student-list"><div class="empty-small">Programdaki dersinizden açabilir veya sınıf/şube/ders seçebilirsiniz.</div></div><button class="btn btn-green" id="saveAtt" disabled>✅ Yoklamayı Kaydet</button></div>`;$("loadAtt").onclick=()=>{const c=$("attClass").value,s=$("attSection").value,l=$("attLesson").value;if(!c||!s||!l)return toast("Sınıf, şube ve ders seçin.");renderAttendanceRows(c,s,l)}}
function openAttendanceFor(x){if(!x)return;subview("teacher","attendance","Yoklama");renderAttendance();setTimeout(()=>{$("attClass").value=x.className.match(/\d+/)?.[0]||5;$("attSection").value=x.section;$("attLesson").value=x.slot;renderAttendanceRows($("attClass").value,x.section,x.slot)},0)}
function renderAttendanceRows(c,s,l){const list=STUDENTS[`${c}-${s}`]||[];$("attendanceRows").innerHTML=`<div class="toolbar"><button class="btn btn-green" id="allPresent">Hepsini Var Yap</button><button class="btn btn-red" id="allAbsent">Hepsini Yok Yap</button><span class="badge badge-blue" id="attCount">${list.length} Öğrenci</span></div>${list.map((st,i)=>`<div class="student-row"><div class="student-meta"><strong>${esc(st.name)}</strong><small>No: ${st.number}</small></div><select class="select attendance-select" data-i="${i}" style="max-width:140px"><option value="present">🟢 Var</option><option value="absent">🔴 Yok</option></select></div>`).join("")}`;$("saveAtt").disabled=list.length===0;$("allPresent").onclick=()=>document.querySelectorAll(".attendance-select").forEach(x=>x.value="present");$("allAbsent").onclick=()=>document.querySelectorAll(".attendance-select").forEach(x=>x.value="absent");$("saveAtt").onclick=()=>saveAttendance(c,s,l,list)}
async function saveAttendance(c,s,l,list){const btn=$("saveAtt");btn.disabled=true;const selects=[...document.querySelectorAll(".attendance-select")];try{for(let i=0;i<list.length;i++)await addDoc(collection(db,"attendance"),{teacherId:state.selectedTeacher.id,teacherName:state.selectedTeacher.name,class:Number(c),section:s,lesson:Number(l),studentName:list[i].name,studentNumber:list[i].number,status:selects[i].value,date:new Date().toISOString().slice(0,10),createdAt:serverTimestamp()});toast("Yoklama kaydedildi.");await loadRecent();renderTeacherHome();renderTeacherHistory()}catch(e){console.error(e);toast("Kayıt başarısız. Firestore Rules'u kontrol edin.")}finally{btn.disabled=false}}
async function loadRecent(){try{const q=query(collection(db,"attendance"),orderBy("createdAt","desc"),limit(300));const snap=await getDocs(q);state.attendance=snap.docs.map(d=>({id:d.id,...d.data()}));}catch{state.attendance=[]}}
function renderTeacherHistory(){const own=state.attendance.filter(x=>x.teacherId===state.selectedTeacher?.id).slice(0,40);$("myHistory").innerHTML=`<div class="panel"><h3>Son Yoklamalarım</h3><div class="table-wrap"><table class="table"><thead><tr><th>Tarih</th><th>Sınıf</th><th>Ders</th><th>Öğrenci</th><th>Durum</th></tr></thead><tbody>${own.map(x=>`<tr><td>${esc(x.date||"-")}</td><td>${x.class}-${esc(x.section||"")}</td><td>${x.lesson}.</td><td>${esc(x.studentName||"")}</td><td><span class="badge ${x.status==="absent"?'badge-red':'badge-green'}">${x.status==="absent"?'Yok':'Var'}</span></td></tr>`).join("")||'<tr><td colspan="5">Henüz kayıt yok.</td></tr>'}</tbody></table></div></div>`}
function renderTeacherStudents(){const t=state.selectedTeacher||{};const sch=getScheduleForTeacher(t);const keys=[...new Set(sch.map(x=>`${x.className.match(/\d+/)?.[0]}-${x.section}`))];let list=keys.flatMap(k=>STUDENTS[k]||[]).slice(0,60);$("myStudents").innerHTML=`<div class="panel"><h3>Atanmış Öğrenciler</h3><div class="toolbar"><span class="badge badge-blue">${list.length} öğrenci gösteriliyor</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Ad Soyad</th><th>Numara</th><th>Sınıf/Şube</th></tr></thead><tbody>${list.map((x,i)=>`<tr><td>${esc(x.name)}</td><td>${x.number}</td><td>${keys[i%keys.length]?.replace('-', ' / ')||'-'}</td></tr>`).join("")}</tbody></table></div></div>`}
function renderTeacherNotices(){$("teacherNotices").innerHTML=`<div class="panel"><h3>Okul Duyuruları</h3>${state.announcements.length?state.announcements.map(a=>`<div class="notice"><div class="notice-title">${esc(a.title)}</div><div class="notice-body">${esc(a.body)}</div></div>`).join(""):'<div class="empty-small">Henüz duyuru yok.</div>'}</div>`}

function renderAdmin(){renderDashboard();renderAdminTeachers();renderAdminStudents();renderClasses();renderSubjects();renderScheduleAdmin();renderAdminAttendance();renderAbsences();renderAnnouncements();renderReports();renderLogs();renderSettings()}
function renderDashboard(){const t=state.teachers.length,s=Object.values(STUDENTS).reduce((a,b)=>a+b.length,0);const absent=state.attendance.filter(x=>x.status==="absent").length;$("dashboard").innerHTML=`<div class="hero-card"><div class="hero-row"><div><div class="eyebrow">ATATÜRK ORTAOKULU</div><h3>Yönetim Merkezi</h3><p>Okulun günlük durumunu tek ekrandan yönetin.</p></div><button class="btn btn-blue" id="autoProgram">🎲 Otomatik Program Oluştur</button></div></div><div class="stats-grid"><div class="stat-card accent-blue"><div class="stat-label">Öğretmen</div><div class="stat-value">${t}</div></div><div class="stat-card accent-green"><div class="stat-label">Öğrenci</div><div class="stat-value">${s}</div></div><div class="stat-card accent-gold"><div class="stat-label">Şube</div><div class="stat-value">52</div></div><div class="stat-card accent-red"><div class="stat-label">Yok Kayıtları</div><div class="stat-value">${absent}</div></div></div><div class="grid-2"><div class="panel"><h3>Hızlı İşlemler</h3><div class="toolbar"><button class="btn btn-green" id="dashTeacher">+ Öğretmen</button><button class="btn btn-purple" id="dashStudent">+ Öğrenci</button><button class="btn btn-gold" id="dashNotice">+ Duyuru</button></div></div><div class="panel"><h3>Sistem</h3><div class="notice"><div class="notice-title">🟢 Firestore veri katmanı</div><div class="notice-body">Bağlantı durumu üst panelde izleniyor.</div></div><div class="notice"><div class="notice-title">52 şube hazır</div><div class="notice-body">Her şubede 30 benzersiz örnek öğrenci bulunuyor.</div></div></div></div>`;$("autoProgram").onclick=()=>{subview("admin","schedule","Ders Programı");generateSchedule()};$("dashTeacher").onclick=()=>openTeacherModal();$("dashStudent").onclick=()=>openStudentModal();$("dashNotice").onclick=()=>openNoticeModal()}
function renderAdminTeachers(){$("teachers").innerHTML=`<div class="panel"><div class="toolbar"><button class="btn btn-blue" id="addTeacher">+ Öğretmen Ekle</button><button class="btn btn-purple" id="refreshTeacher">↻ Yenile</button><span class="badge badge-blue">${state.teachers.length} kayıt</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Ad Soyad</th><th>Branş</th><th>Durum</th><th>İşlem</th></tr></thead><tbody>${state.teachers.map(t=>`<tr><td>${esc(t.name)}</td><td>${esc(t.branch||'-')}</td><td><span class="badge ${t.active!==false?'badge-green':'badge-red'}">${t.active!==false?'Aktif':'Pasif'}</span></td><td><button class="btn btn-red" data-del-teacher="${t.id}">🗑 Sil</button></td></tr>`).join("")||'<tr><td colspan="4">Henüz öğretmen yok.</td></tr>'}</tbody></table></div></div>`;$("addTeacher").onclick=openTeacherModal;$("refreshTeacher").onclick=async()=>{await loadTeachers();toast("Öğretmen listesi yenilendi.")};document.querySelectorAll("[data-del-teacher]").forEach(b=>b.onclick=()=>deleteTeacher(b.dataset.delTeacher))}
function openTeacherModal(){modal(`<h3>Yeni Öğretmen Ekle</h3><div class="form-stack"><input id="mFirst" class="input" placeholder="Ad"><input id="mLast" class="input" placeholder="Soyad"><select id="mBranch" class="select">${BRANCHES.map(b=>`<option>${b}</option>`).join("")}</select><button class="btn btn-green" id="mSave">Kaydet</button></div>`);$("mSave").onclick=async()=>{const first=$("mFirst").value.trim(),last=$("mLast").value.trim();if(!first||!last)return toast("Ad ve soyad zorunlu.");await addDoc(collection(db,"teachers"),{name:first+" "+last,branch:$("mBranch").value,createdAt:serverTimestamp(),active:true});closeModal();await loadTeachers();renderAdmin();toast("Öğretmen eklendi.")}}
async function deleteTeacher(id){const t=state.teachers.find(x=>x.id===id);if(!t||!confirm(`${t.name} isimli öğretmeni silmek istediğinize emin misiniz?`))return;try{if(!id.startsWith("local-"))await deleteDoc(doc(db,"teachers",id));state.teachers=state.teachers.filter(x=>x.id!==id);renderAdminTeachers();renderTeacherChoices();toast("Öğretmen silindi.")}catch(e){toast("Silme işlemi başarısız.")}}
function renderAdminStudents(){let rows=Object.entries(STUDENTS).flatMap(([key,arr])=>arr.slice(0,2).map(s=>({...s,key})));$("students").innerHTML=`<div class="panel"><div class="toolbar"><button class="btn btn-purple" id="addStudent">+ Öğrenci Ekle</button><input id="studentSearchAdmin" class="input" placeholder="Öğrenci ara..." style="max-width:300px"></div><div class="table-wrap"><table class="table"><thead><tr><th>Ad Soyad</th><th>Numara</th><th>Sınıf/Şube</th></tr></thead><tbody id="studentAdminBody">${rows.map(s=>`<tr><td>${esc(s.name)}</td><td>${s.number}</td><td>${s.key.replace('-', ' / ')}</td></tr>`).join("")}</tbody></table></div></div>`;$("addStudent").onclick=openStudentModal;$("studentSearchAdmin").oninput=e=>{const q=e.target.value.toLocaleLowerCase("tr-TR");$("studentAdminBody").innerHTML=rows.filter(s=>s.name.toLocaleLowerCase("tr-TR").includes(q)||String(s.number).includes(q)).map(s=>`<tr><td>${esc(s.name)}</td><td>${s.number}</td><td>${s.key.replace('-', ' / ')}</td></tr>`).join("")}}
function openStudentModal(){modal(`<h3>Yeni Öğrenci</h3><div class="form-stack"><input id="sName" class="input" placeholder="Ad Soyad"><input id="sNo" class="input" placeholder="Öğrenci No"><select id="sClass" class="select">${[5,6,7,8].map(x=>`<option value="${x}">${x}. Sınıf</option>`).join("")}</select><select id="sSec" class="select">${SECTIONS.map(x=>`<option>${x}</option>`).join("")}</select><button class="btn btn-purple" id="sSave">Kaydet</button></div>`);$("sSave").onclick=async()=>{const name=$("sName").value.trim(),number=Number($("sNo").value);if(!name||!number)return toast("Ad ve numara zorunlu.");const key=`${$("sClass").value}-${$("sSec").value}`;try{await addDoc(collection(db,"students"),{name,number,class:Number($("sClass").value),section:$("sSec").value,createdAt:serverTimestamp()});toast("Öğrenci Firestore'a eklendi.")}catch{toast("Öğrenci kaydedilemedi.")}closeModal();}}
function renderClasses(){$("classes").innerHTML=`<div class="panel"><div class="toolbar"><span class="badge badge-blue">52 Şube</span><span class="badge badge-green">30 öğrenci / şube</span></div><div class="schedule-grid">${[5,6,7,8].flatMap(g=>SECTIONS.map(sec=>`<div class="day-col" style="min-height:auto"><h4>${g}-${sec}</h4><div class="empty-small">${STUDENTS[`${g}-${sec}`]?.length||0} öğrenci</div><button class="btn btn-muted" style="margin-top:9px" data-class-view="${g}-${sec}">Öğrencileri Gör</button></div>`)).join("")}</div></div>`;document.querySelectorAll("[data-class-view]").forEach(b=>b.onclick=()=>toast(`${b.dataset.classView} sınıfında 30 öğrenci bulunuyor.`))}
function renderSubjects(){$("subjects").innerHTML=`<div class="panel"><div class="toolbar"><button class="btn btn-blue">+ Ders Ekle</button></div><div class="schedule-grid">${BRANCHES.map((b,i)=>`<div class="day-col" style="min-height:auto"><h4>${i+1} • ${b}</h4><div class="empty-small">Aktif ders</div></div>`).join("")}</div></div>`}
let generatedSchedule=[];
function generateSchedule(){const teachers=state.teachers.filter(t=>t.active!==false);generatedSchedule=[];for(const day of DAYS){const usedTeachers=new Set();for(let slot=1;slot<=7;slot++){for(const teacher of [...teachers].sort(()=>Math.random()-.5)){if(usedTeachers.has(teacher.id))continue;const classKey=`${5+((slot+day.length)%4)}-${SECTIONS[(slot+day.length+teacher.name.length)%SECTIONS.length]}`;const branch=teacher.branch||BRANCHES[teacher.name.length%BRANCHES.length];const already=generatedSchedule.some(x=>x.day===day&&x.slot===slot&&x.classKey===classKey&&x.branch===branch);if(already)continue;generatedSchedule.push({day,slot,teacherId:teacher.id,teacherName:teacher.name,classKey,branch});usedTeachers.add(teacher.id);break}}}renderScheduleAdmin();toast(`Otomatik program üretildi: ${generatedSchedule.length} atama.`)}
function renderScheduleAdmin(){$("schedule").innerHTML=`<div class="panel"><div class="toolbar"><button class="btn btn-blue" id="genSchedule">🎲 Otomatik Program Oluştur</button><button class="btn btn-purple" id="shuffleSchedule">🔄 Yeniden Karıştır</button><button class="btn btn-gold" id="lockSchedule">🔒 Programı Kilitle</button><span class="badge badge-blue">${generatedSchedule.length} atama</span></div><div class="schedule-grid">${DAYS.map(day=>`<div class="day-col"><h4>${day}</h4>${generatedSchedule.filter(x=>x.day===day).map(x=>`<div class="slot"><strong>${x.slot}. Ders • ${x.classKey}</strong><small>${esc(x.branch)} • ${esc(x.teacherName)}</small></div>`).join("")||'<div class="empty-small">Henüz oluşturulmadı.</div>'}</div>`).join("")}</div></div>`;$("genSchedule").onclick=generateSchedule;$("shuffleSchedule").onclick=generateSchedule;$("lockSchedule").onclick=()=>toast("Program kilitlendi (bu oturum için).")}
function renderAdminAttendance(){$("adminAttendance").innerHTML=`<div class="panel"><h3>Son Yoklama Kayıtları</h3><div class="table-wrap"><table class="table"><thead><tr><th>Tarih</th><th>Öğretmen</th><th>Sınıf</th><th>Öğrenci</th><th>Durum</th></tr></thead><tbody>${state.attendance.slice(0,80).map(x=>`<tr><td>${esc(x.date||'-')}</td><td>${esc(x.teacherName||'-')}</td><td>${x.class}-${esc(x.section||'')}</td><td>${esc(x.studentName||'')}</td><td><span class="badge ${x.status==='absent'?'badge-red':'badge-green'}">${x.status==='absent'?'Yok':'Var'}</span></td></tr>`).join('')||'<tr><td colspan="5">Kayıt yok.</td></tr>'}</tbody></table></div></div>`}
function renderAbsences(){const abs=state.attendance.filter(x=>x.status==='absent').slice(0,100);$("absences").innerHTML=`<div class="panel"><div class="toolbar"><span class="badge badge-red">${abs.length} devamsızlık kaydı</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Tarih</th><th>Öğrenci</th><th>Numara</th><th>Sınıf</th><th>Öğretmen</th></tr></thead><tbody>${abs.map(x=>`<tr><td>${esc(x.date||'-')}</td><td>${esc(x.studentName||'')}</td><td>${x.studentNumber||''}</td><td>${x.class}-${esc(x.section||'')}</td><td>${esc(x.teacherName||'')}</td></tr>`).join('')||'<tr><td colspan="5">Devamsızlık kaydı yok.</td></tr>'}</tbody></table></div></div>`}
function renderAnnouncements(){$("announcements").innerHTML=`<div class="panel"><div class="toolbar"><button class="btn btn-gold" id="newNotice">+ Duyuru Yayınla</button></div>${state.announcements.map(a=>`<div class="notice"><div class="notice-title">${esc(a.title)}</div><div class="notice-body">${esc(a.body)}</div></div>`).join('')||'<div class="empty-small">Henüz duyuru yok.</div>'}</div>`;$("newNotice").onclick=openNoticeModal}
function openNoticeModal(){modal(`<h3>Duyuru Yayınla</h3><div class="form-stack"><input id="nTitle" class="input" placeholder="Başlık"><textarea id="nBody" class="input" placeholder="Duyuru metni" rows="5"></textarea><button class="btn btn-gold" id="nSave">Yayınla</button></div>`);$("nSave").onclick=()=>{const title=$("nTitle").value.trim(),body=$("nBody").value.trim();if(!title||!body)return toast("Başlık ve metin zorunlu.");state.announcements.unshift({title,body});closeModal();renderAnnouncements();renderTeacherNotices();toast("Duyuru yayınlandı.")}}
function renderReports(){const absent=state.attendance.filter(x=>x.status==='absent').length;$("reports").innerHTML=`<div class="grid-2"><div class="panel"><h3>Günlük Özet</h3><div class="stats-grid"><div class="stat-card"><div class="stat-label">Var</div><div class="stat-value">${state.attendance.filter(x=>x.status==='present').length}</div></div><div class="stat-card accent-red"><div class="stat-label">Yok</div><div class="stat-value">${absent}</div></div></div><button class="btn btn-blue" id="csvReport">CSV Raporu Hazırla</button></div><div class="panel"><h3>Hızlı Raporlar</h3><div class="toolbar"><button class="btn btn-muted">Sınıf Raporu</button><button class="btn btn-muted">Öğretmen Raporu</button><button class="btn btn-muted">Öğrenci Raporu</button></div></div></div>`;$("csvReport").onclick=exportCsv}
function exportCsv(){const rows=state.attendance.map(x=>[x.date,x.teacherName,x.class,x.section,x.lesson,x.studentName,x.studentNumber,x.status]);const csv=[['Tarih','Öğretmen','Sınıf','Şube','Ders','Öğrenci','No','Durum'],...rows].map(r=>r.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(';')).join('\n');const blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='ataturk-ortaokulu-yoklama.csv';a.click();URL.revokeObjectURL(a.href)}
function renderLogs(){$("logs").innerHTML=`<div class="panel"><h3>İşlem Geçmişi</h3><div class="empty-small">Bu sürümde kritik işlemler yerel oturumda tutulur. Canlı kullanım için yönetici yetkisi ve gerçek audit log Firestore Rules ile ayrıca kilitlenmelidir.</div></div>`}
function renderSettings(){$("settings").innerHTML=`<div class="panel"><h3>Okul Ayarları</h3><div class="form-grid"><input class="input" value="Atatürk Ortaokulu"><input class="input" value="2026–2027 Eğitim Öğretim Yılı"><input class="input" value="5 gün"><input class="input" value="Günde 7 ders"></div><div class="toolbar" style="margin-top:15px"><span class="badge badge-blue">PWA aktif</span><span class="badge badge-green">Responsive</span><span class="badge badge-gold">Otomasyon motoru</span></div></div>`}
function modal(content){$("modalRoot").innerHTML=`<div class="modal-backdrop"><div class="modal"><div class="modal-head"><div></div><button class="icon-btn" id="closeModal">✕</button></div>${content}</div></div>`;$("closeModal").onclick=closeModal} function closeModal(){$('modalRoot').innerHTML=''}
function setupNav(){document.querySelectorAll("#adminNav .nav-btn").forEach(b=>b.addEventListener("click",()=>{const id=b.dataset.adminView;const title=b.textContent.trim().replace(/^\S+\s/,'');subview("admin",id,title)}));document.querySelectorAll("#teacherNav .nav-btn").forEach(b=>b.addEventListener("click",()=>{const id=b.dataset.teacherView;const title=b.textContent.trim().replace(/^\S+\s/,'');subview("teacher",id,title)}));$("adminExit").onclick=()=>show("welcome");$("teacherExit").onclick=()=>{state.selectedTeacher=null;show("welcome")}}
function setConnection(online){state.online=online;const entries=[["connectionDot","connectionText"],["teacherDot","teacherConnection"],["adminDot","adminConnection"]];entries.forEach(([d,t])=>{if($(d))$(d).className='dot';if($(t))$(t).textContent=online?'Bağlı':'Bağlantı kesildi';if($(d))$(d).style.background=online?'#22c55e':'#ef4444'})}
window.addEventListener('online',()=>setConnection(true));window.addEventListener('offline',()=>setConnection(false));
$("teacherEntry").onclick=async()=>{show("teacherSelect");await loadTeachers()};$("adminEntry").onclick=async()=>{show("adminApp");await loadTeachers();await loadRecent();renderAdmin();};$("teacherSearch").oninput=renderTeacherChoices;document.querySelectorAll("[data-back]").forEach(b=>b.onclick=()=>show("welcome"));setupNav();setConnection(navigator.onLine);
(async()=>{await loadTeachers();await loadRecent();})();
if('serviceWorker' in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js').catch(console.error));
